autocounter(autox){
returnbenchmark::Counter{static_cast<double>(x),benchmark::Counter::kDefaults};
}
autocounter_avg(autox){
returnbenchmark::Counter{static_cast<double>(x),benchmark::Counter::kAvgIterations};
