enumclassProblemType{
WangBoyd2008,
WangBoyd2008Width,
Domahidi2012,
ActiveStateConstr,
};
conststd::map<std::string,ProblemType>problem_type_map{
{"wang-boyd-2008",ProblemType::WangBoyd2008},
{"wang-boyd-2008-width",ProblemType::WangBoyd2008Width},
{"domahidi-2012",ProblemType::Domahidi2012},
{"active-state-constr",ProblemType::ActiveStateConstr},
};

structOptions{
boolcold=true;
boolwarm_shift=true;
boolwarm_copy=false;
boolno_updates=false;
std::vector<int>parallelism={8};
std::vector<int>vector_length={v};
boolrm=false;
boolcm=true;
boolpcr=true;
#ifWITH_HPIPM
boolhpipm=true;
#else
boolhpipm=false;
#endif
std::vector<int>horizon{32,64,96,128,192,256};
std::vector<int>masses{6,12,30};
uint64_tnum_instances=50;
uint64_tseed=0;
ProblemTypeproblem_type=ProblemType::WangBoyd2008;
doublepcr_max_update_fraction=0.25;
doublecr_max_update_fraction=0.9;
intparallel_solve_cr_threshold=10;
intparallel_factor_pcr_threshold=20;
doublechanging_constr_factor=0.01;
boolcustom_reporter=true;
boolprint_extra=false;
booluse_color=false;
booltrace=false;
std::stringexport_problem{};
};

namespaceqp=cyqlone::qpalm;
usingcyqlone::index_t;
usingcyqlone::real_t;
usingqp::problems::SpringMassParams;
usingseconds=std::chrono::duration<double>;

qp::problems::SpringMassProblemcreate_problem(constSpringMassParams&params){
autoproblem=qp::problems::spring_mass(params);
//Addarandomdisturbancetotheinitialpositionofthemasses
std::seed_seqseed{params.seed,params.seed>>32};
std::mt19937rng{seed};
usingdist_t=std::uniform_real_distribution<real_t>;
autodist=params.p_max>1?dist_t{-3,3}:dist_t{-0.6,-0.1};
for(index_tr=0;r<static_cast<index_t>(params.masses.size());++r)
problem.ocp.b(0)(r,0)+=dist(rng);
returnproblem;
}

#ifGUANAQO_WITH_TRACING
std::map<std::string,fs::path>traces;
voiddisable_tracing(){guanaqo::get_trace_logger().logs.resize(0);}
voidtrace_run(auto&&fun,constauto&name){
std::filesystem::pathout_dir{"traces"};
out_dir/=*cyqlone_commit_hash?cyqlone_commit_hash:"unknown";
std::filesystem::pathout_file=out_dir/name;
if(auto[_,ins]=traces.try_emplace(name,out_file);!ins)
return;
#ifGUANAQO_WITH_PERFETTO
#ifGUANAQO_WITH_PCM_TRACING
guanaqo::pcm::enable_counters();
#endif
fun();//warmup
autotrace=guanaqo::trace::start_tracing(2*1024*1024);
fun();
#ifGUANAQO_WITH_PCM_TRACING
guanaqo::pcm::disable_counters();
#endif
guanaqo::trace::stop_tracing(std::move(trace),out_file.replace_extension(".pftrace"));
#else
guanaqo::get_trace_logger().reset();
guanaqo::get_trace_logger().logs.resize(0);
guanaqo::get_trace_logger().logs.reserve(1'048'576);
fun();//warmup
guanaqo::get_trace_logger().reset();
guanaqo::get_trace_logger().logs.resize(1'048'576);
fun();
std::filesystem::create_directories(out_dir);
std::ofstreamcsv{out_file.replace_extension(".csv")};
autologs=guanaqo::get_trace_logger().get_logs();
guanaqo::TraceLogger::write_column_headings(csv)<<'\n';
for(constauto&log:logs)
csv<<log<<'\n';
#ifCYQLONE_WITH_ZLIB
cyqlone::write_chrome_trace(out_file.replace_extension(".json.gz"),logs);
#endif
#endif
}
voidprint_traces(std::ostream&os){
for(constauto&[_,pth]:traces)
os<<pth<<'\n';
}
#else
voiddisable_tracing(){}
voidtrace_run(auto&&,constauto&){}
voidprint_traces(std::ostream&){}
#endif

template<index_tVL,qp::StorageOrderOrder>
voidrun_benchmark(benchmark::State&state,[[maybe_unused]]conststd::string&param_name,
constSpringMassParams&params,qp::CyQPALMBackendSettingsbackend_settings,
qp::Settingssettings,boolwarm=false,booltrace=false)try{
disable_tracing();//Notracingduringtheactualbenchmark
if(backend_settings.processors<1)
returnstate.SkipWithMessage("Numberofprocessorsmustbeatleast1.");
autoproblem=create_problem(params);
//BuildaQPALMCyqlonesolver
autoocp=cyqlone::CyqloneStorage<>::build(problem.ocp);
autobackend=qp::make_cyqpalm_backend<VL, Order>(ocp,{},backend_settings);
qp::Solver<qp::CyQPALMBackend<VL, Order>*>qpalm{backend.get(),settings};
//Mainbenchmark
qp::SolverStatusstatus;
doubletime_solve=0,time_active_set_change=0,time_line_search=0,
time_recompute_outer=0,time_recompute_inner=0,time_mat_vec=0;
qpalm();//Warmup
if(warm){
constautonx=problem.ocp.dim.nx,nu=problem.ocp.dim.nu;
qpalm.warm_start_solution();
autox=qpalm.get_solution();
std::copy_n(x.data()+nu,nx,problem.ocp.b(0).data);
ocp.update(problem.ocp);
update_cyqpalm_backend(*qpalm.backend,ocp);
}
for(auto_:state){
status=qpalm();
state.SetIterationTime(seconds(qpalm.stats->timings.total.wall_time).count());
time_solve+=seconds(qpalm.stats->timings.solve.wall_time).count();
time_active_set_change+=seconds(qpalm.stats->timings.active_set_change.wall_time).count();
time_line_search+=seconds(qpalm.stats->timings.line_search.wall_time).count();
time_recompute_outer+=seconds(qpalm.stats->timings.recompute_outer.wall_time).count();
time_recompute_inner+=seconds(qpalm.stats->timings.recompute_inner.wall_time).count();
time_mat_vec+=seconds(qpalm.stats->timings.mat_vec_A.wall_time).count();
time_mat_vec+=seconds(qpalm.stats->timings.mat_vec_AT.wall_time).count();
time_mat_vec+=seconds(qpalm.stats->timings.mat_vec_M.wall_time).count();
time_mat_vec+=seconds(qpalm.stats->timings.mat_vec_MT.wall_time).count();
time_mat_vec+=seconds(qpalm.stats->timings.mat_vec_Q.wall_time).count();
}
if(trace)
trace_run([&]{qpalm();},param_name);
autosol=ocp.reconstruct_solution(problem.ocp,qpalm.get_solution(),
qpalm.get_inequality_multipliers(),
qpalm.get_equality_multipliers());
autokkt_error=problem.ocp.compute_kkt_error(sol);

state.counters["status"]=counter(status);
state.counters["success"]=counter(status==qp::SolverStatus::Converged);
state.counters["iter"]=counter(qpalm.stats->inner_iter);
state.counters["outer_iter"]=counter(qpalm.stats->outer_iter);
state.counters["num_factor"]=counter(qpalm.stats_backend->num_factor);
state.counters["num_upd"]=counter(qpalm.stats_backend->num_updates);
state.counters["rank_upd"]=counter(qpalm.stats_backend->rank_updates);
state.counters["t_solve"]=counter_avg(time_solve);
state.counters["t_active_set_change"]=counter_avg(time_active_set_change);
state.counters["t_line_search"]=counter_avg(time_line_search);
state.counters["t_recompute_outer"]=counter_avg(time_recompute_outer);
state.counters["t_recompute_inner"]=counter_avg(time_recompute_inner);
state.counters["t_mat_vec"]=counter_avg(time_mat_vec);
state.counters["res_dual"]=counter(kkt_error.stationarity);
state.counters["res_eq"]=counter(kkt_error.equality_residual);
state.counters["res_ineq"]=counter(kkt_error.inequality_residual);
state.counters["compl"]=counter(kkt_error.complementarity);
}catch(conststd::exception&e){
state.SkipWithError(e.what());
}

enumclassWarmStartHPIPM{
NoWarmStart,
WarmZero,
WarmCopy,
WarmShift,
};

#ifWITH_HPIPM
voidrun_benchmark_hpipm(benchmark::State&state,constSpringMassParams&params,
WarmStartHPIPMwarm=WarmStartHPIPM::NoWarmStart){
autoproblem=create_problem(params);
autoqp_data=build_hpipm_qp(problem.ocp);
autosolver_data=create_hpipm_solver(qp_data,warm!=WarmStartHPIPM::NoWarmStart?1:0);
//Mainbenchmark
solve_hpipm(*qp_data,*solver_data);//Warmup
std::optional<cyqlone::LinearOCPStorage::Solution>prev_sol;
if(warm!=WarmStartHPIPM::NoWarmStart){
prev_sol=get_solution_hpipm(*solver_data);
update_x0_hpipm(problem.ocp,*qp_data,prev_sol->solution);
if(warm==WarmStartHPIPM::WarmZero)
std::ranges::fill(prev_sol->solution,real_t{0});
elseif(warm==WarmStartHPIPM::WarmShift)
shift_solution_hpipm(*qp_data,prev_sol->solution);
}
for(auto_:state){
if(prev_sol)
warm_start_hpipm(*solver_data,prev_sol->solution);
autotime_solve=solve_hpipm(*qp_data,*solver_data);
state.SetIterationTime(seconds(time_solve).count());
}
autosol=get_solution_hpipm(*solver_data);
autokkt_error=problem.ocp.compute_kkt_error(sol);
autostats=get_stats_hpipm(*solver_data);
state.counters["status"]=counter(stats.status);
state.counters["success"]=counter(stats.status==0);
state.counters["iter"]=counter(stats.iter);
state.counters["max_res_stat"]=counter(stats.max_res_stat);
state.counters["max_res_eq"]=counter(stats.max_res_eq);
state.counters["max_res_ineq"]=counter(stats.max_res_ineq);
state.counters["max_res_comp"]=counter(stats.max_res_comp);
state.counters["res_dual"]=counter(kkt_error.stationarity);
state.counters["res_eq"]=counter(kkt_error.equality_residual);
state.counters["res_ineq"]=counter(kkt_error.inequality_residual);
state.counters["compl"]=counter(kkt_error.complementarity);
}
#endif

structProblem{
std::stringname;
SpringMassParamsparams;
};

std::generator<Problem>get_spring_mass_params(constOptions&opts){
usingstd::format;
for(autoM:opts.masses)
for(autoN:opts.horizon)
for(uint64_tseed=opts.seed;seed<opts.seed+opts.num_instances;++seed)
switch(opts.problem_type){
caseProblemType::WangBoyd2008:
co_yield{
.name=format("spring-mass(M={},N={},seed={})wb2008",M,N,seed),
.params=SpringMassParams::wang_boyd_2008(M,N,seed),
};
break;
caseProblemType::WangBoyd2008Width:
co_yield{
.name=format("spring-mass(M={},N={},seed={})wb2008w",M,N,seed),
.params=SpringMassParams::wang_boyd_2008_width(M,N,seed,1),
};
break;
caseProblemType::Domahidi2012:
co_yield{
.name=format("spring-mass(M={},N={},seed={})d2012",M,N,seed),
.params=SpringMassParams::domahidi_2012(M,N,seed),
};
break;
caseProblemType::ActiveStateConstr:
co_yield{
.name=format("spring-mass(M={},N={},seed={})act",M,N,seed),
.params=SpringMassParams::active_state_constr(M,N,seed),
};
break;
default:throwstd::runtime_error("Unknownproblemtype");
}
}

voidexport_problem(constOptions&opts){
if(opts.export_problem.empty())
return;
for(constauto&params:get_spring_mass_params(opts)){
autoproblem=create_problem(params.params);
fs::pathfilename=opts.export_problem;
if(fs::is_directory(filename))
filename/=params.name+".mat";
automat=cyqlone::create_mat(filename);
cyqlone::add_to_mat(mat.get(),"ocp",problem.ocp);
std::cout<<"Exportedproblem"<<params.name<<"to"<<filename<<std::endl;
break;
}
}

structSolver{
std::stringname;
std::function<void(benchmark::State&,SpringMassParams)>run;
};

std::string_vieworder(qp::StorageOrdero){returno==qp::StorageOrder::RowMajor?"rm":"cm";}

template<index_tVL,qp::StorageOrderO>
std::generator<Solver>get_cyqlone_solvers(constOptions&opts){
constautocyqlone_solver=[trace{opts.trace}](std::string_viewname,
constqp::CyQPALMBackendSettings&backend,
constqp::Settings&settings){
constautoparam_name=
std::format("cyqlone(p={},v={},{},{})",backend.processors,VL,order(O),name);
returnSolver{param_name,[=](benchmark::State&state,constSpringMassParams&params){
run_benchmark<VL, O>(state,param_name,params,backend,settings,true,
trace);
}};
};
for(autop:opts.parallelism){
qp::CyQPALMBackendSettingsbackend{
.processors=p,
.changing_constr_factor=opts.changing_constr_factor,
.max_update_count=20,
.tricyqle_params=
{
.pcr_max_update_fraction=opts.pcr_max_update_fraction,
.cr_max_update_fraction_Y0=opts.cr_max_update_fraction,
.parallel_solve_cr_threshold=opts.parallel_solve_cr_threshold,
.parallel_factor_pcr_threshold=opts.parallel_factor_pcr_threshold,
},
};
qp::Settingssettings{
.tolerance=1e-8,
.dual_tolerance=1e-8,
.initial_penalty_y=20,
.verbose=false,
};
qp::CyQPALMBackendSettingsbackend_no_upd=backend;
backend_no_upd.max_update_count=0;
qp::Settingssettings_warm=settings;
settings_warm.initial_penalty_y=1e4;
settings_warm.initial_inner_tolerance=1e-4;
if(opts.pcr)
backend.tricyqle_params.solve_method=cyqlone::SolveMethod::PCR;
if(opts.cold){
backend.strategy=backend_no_upd.strategy=qp::WarmStartingStrategy::Zeros;
co_yieldcyqlone_solver("zero",backend,settings);
if(opts.no_updates)
co_yieldcyqlone_solver("zero,upd=0",backend_no_upd,settings);
}
if(opts.warm_shift){
backend.strategy=backend_no_upd.strategy=qp::WarmStartingStrategy::Shift;
co_yieldcyqlone_solver("shift",backend,settings_warm);
if(opts.no_updates)
co_yieldcyqlone_solver("shift,upd=0",backend_no_upd,settings_warm);
}
if(opts.warm_copy){
backend.strategy=backend_no_upd.strategy=qp::WarmStartingStrategy::Copy;
co_yieldcyqlone_solver("copy",backend,settings_warm);
if(opts.no_updates)
co_yieldcyqlone_solver("copy,upd=0",backend_no_upd,settings_warm);
}
}
}

std::generator<Solver>get_hpipm_solvers(constOptions&opts){
if(opts.hpipm){
#ifWITH_HPIPM
if(opts.cold)
co_yield{"hpipm(zero)",[=](benchmark::State&state,constSpringMassParams&params){
run_benchmark_hpipm(state,params,WarmStartHPIPM::WarmZero);
}};
if(opts.warm_shift)
co_yield{"hpipm(shift)",[=](benchmark::State&state,constSpringMassParams&params){
run_benchmark_hpipm(state,params,WarmStartHPIPM::WarmShift);
}};
if(opts.warm_copy)
co_yield{"hpipm(copy)",[=](benchmark::State&state,constSpringMassParams&params){
run_benchmark_hpipm(state,params,WarmStartHPIPM::WarmCopy);
}};
#else
throwstd::invalid_argument("HPIPMsupportnotenabledinthisbuild");
#endif
}
}

usingstd::ranges::elements_of;

template<qp::StorageOrderOrder>
std::generator<Solver>get_cyqlone_solvers_vl(constOptions&opts){
staticconstexprautoVLs=batmat::types::vl_for_real_t;
staticconstexprautoto_string=[](autovl){returnstd::to_string(vl);};
staticconstexprautolut=guanaqo::make_lut<VLs>([]<index_tVL>(batmat::index_constant<VL>){
returnstd::make_pair(VL,get_cyqlone_solvers<VL, Order>);
});
for(autov:opts.vector_length){
autodispatch=std::ranges::find(lut,v,&decltype(lut)::value_type::first);
if(dispatch==lut.end())
throwstd::invalid_argument("Unsupportedvectorlength.Supportedlengths:"+
guanaqo::join(std::views::transform(VLs,to_string)));
co_yieldelements_of(dispatch->second(opts));
}
}

std::generator<Solver>get_solvers(constOptions&opts){
co_yieldelements_of(get_hpipm_solvers(opts));
if(opts.rm)
co_yieldelements_of(get_cyqlone_solvers_vl<qp::StorageOrder::RowMajor>(opts));
if(opts.cm)
co_yieldelements_of(get_cyqlone_solvers_vl<qp::StorageOrder::ColMajor>(opts));
}

autoregister_benchmarks(constOptions&opts){
size_tmax_problem_name_len=0;
size_tmax_solver_name_len=0;
for(autoproblem:get_spring_mass_params(opts)){
max_problem_name_len=std::max(max_problem_name_len,problem.name.size());
for(autosolver:get_solvers(opts)){
max_solver_name_len=std::max(max_solver_name_len,solver.name.size());
benchmark::RegisterBenchmark(std::format("{}@{}",problem.name,solver.name),
[params=problem.params,run=std::move(solver.run)](
benchmark::State&state){run(state,params);})
->MeasureProcessCPUTime()
->UseManualTime()
->Unit(benchmark::kMillisecond)
->ComputeStatistics("max",[](auto&v){return*std::ranges::max_element(v);})
->ComputeStatistics("min",[](auto&v){return*std::ranges::min_element(v);})
->GetName();
}
}
returnstd::make_pair(max_problem_name_len,max_solver_name_len);
}

std::unique_ptr<benchmark::BenchmarkReporter>make_custom_reporter(size_tproblem_name_width,
size_tsolver_name_width,
boolprint_extra,
boolwith_color);

voidregister_options(constchar*program,CLI::App&app,Options&opts){
if(std::getenv("NO_COLOR"))
opts.use_color=false;
elseif(std::getenv("CLICOLOR_FORCE"))
opts.use_color=true;
else
opts.use_color=isatty(fileno(stdout))==1;
#ifBATMAT_WITH_OPENMP
opts.parallelism={omp_get_max_threads()};
#endif
app.usage(std::string(program)+"[options]--[benchmarkoptions]");
app.footer(std::format("BenchmarkoptionsarepassedtotheGoogleBenchmarkframework."
"Use{}----helporsee"
"https://google.github.io/benchmark/user_guide.htmlfordetails.",
program));
app.allow_extras();
app.add_flag("--cold,!--no-cold",opts.cold,"Benchmarkwithcoldstarting");
app.add_flag("--warm-shift,!--no-warm-shift",opts.warm_shift,
"Benchmarkwithwarmstarting(shift)");
app.add_flag("--warm-copy,!--no-warm-copy",opts.warm_copy,
"Benchmarkwithwarmstarting(copy)");
app.add_option("--horizon,-N",opts.horizon,"Specifyahorizonlengthtobenchmark");
app.add_option("--masses,-M",opts.masses,"Specifythenumberofmassestobenchmark");
app.add_option("--num-instances,-I",opts.num_instances,
"Numberofrandomprobleminstancestogenerateforeach(M,N)pair");
app.add_option("--seed,-s",opts.seed,"Randomseedforprobleminstancegeneration");
app.add_flag("--no-updates",opts.no_updates,"ComparetotheCyqlonebackendwithoutupdates");
app.add_option("--parallelism,-p",opts.parallelism,
"ThenumberofthreadstouseintheCyqlonebackend");
app.add_option("--vector-length,-v",opts.vector_length,
"ThevectorlengthtouseintheCyqlonebackend");
app.add_flag("--rm,!--no-rm",opts.rm,"Userow-major(default)storage");
app.add_flag("--cm,!--no-cm",opts.cm,"Usecolumn-majorstorage");
app.add_flag("--pcr,!--pcg",opts.pcr,"UseparallelcyclicreductionintheCyqlonebackend");
app.add_flag("--hpipm,!--no-hpipm",opts.hpipm,"UseHPIPMsolverforcomparison");
app.add_option("--problem",opts.problem_type,"Problemtypetobenchmark")
->transform(CLI::CheckedTransformer(problem_type_map,CLI::ignore_case));
app.add_option("--pcr-max-update-fraction",opts.pcr_max_update_fraction,
"MaximumupdaterankfractionwhenusingPCR");
app.add_option("--cr-max-update-fraction",opts.cr_max_update_fraction,
"MaximumupdaterankfractionwhenusingCR");
app.add_option("--changing-constr-factor",opts.changing_constr_factor,
"ChangingconstraintsfactorfortheCyqlonebackend");
app.add_option("--parallel-solve-cr-threshold",opts.parallel_solve_cr_threshold,
"ParallelCRsolvethresholdfortheCyqlonebackend");
app.add_option("--parallel-factor-pcr-threshold",opts.parallel_factor_pcr_threshold,
"ParallelPCRfactorizationthresholdfortheCyqlonebackend");
app.add_option("--export-problem",opts.export_problem,
"Exportasingleprobleminstancetoa.matfile");
app.add_flag("--trace,!--no-trace",opts.trace,"EnabletracingofCyQPALMsolverruns");
app.add_flag("--custom-reporter,!--no-custom-reporter",opts.custom_reporter,
"Usecustombenchmarkreporter");
app.add_flag("--print-extra,!--no-print-extra",opts.print_extra,
"Printadditionalcountersinthebenchmarkreport");
app.add_flag("--color,!--no-color",opts.use_color,"Enable/disablecoloredoutput");
}

intinitialize_google_benchmark(char*program,autobm_args){
if(!bm_args.empty()&&bm_args.front()=="--")
bm_args.erase(bm_args.begin());
std::vector<char*>bm_argv(bm_args.size()+2);
std::ranges::transform(bm_args,bm_argv.begin()+1,[](auto&s){returns.data();});
bm_argv[0]=program;
autobm_argc=static_cast<int>(bm_args.size())+1;
benchmark::Initialize(&bm_argc,bm_argv.data());
if(benchmark::ReportUnrecognizedArguments(bm_argc,bm_argv.data()))
return1;
return0;
}

voidregister_context(){
#ifBATMAT_WITH_OPENMP
autoplaces=std::getenv("OMP_PLACES");
benchmark::AddCustomContext("OMP_NUM_THREADS",std::to_string(omp_get_max_threads()));
benchmark::AddCustomContext("OMP_PLACES",places?places:"");
#endif
benchmark::AddCustomContext("batmat_build_time",batmat_build_time);
benchmark::AddCustomContext("batmat_commit_hash",batmat_commit_hash);
benchmark::AddCustomContext("cyqlone_build_time",cyqlone_build_time);
benchmark::AddCustomContext("cyqlone_commit_hash",cyqlone_commit_hash);
benchmark::AddCustomContext("real_t",guanaqo::demangled_typename(typeid(real_t)));
benchmark::AddCustomContext("index_t",guanaqo::demangled_typename(typeid(index_t)));
#ifGUANAQO_WITH_MKL
MKLVersionVersion;
mkl_get_version(&Version);
benchmark::AddCustomContext("blas_library","MKL");
benchmark::AddCustomContext("blas_version",
std::format("{}.{}.{}({})for{}:{}",Version.MajorVersion,
Version.MinorVersion,Version.UpdateVersion,
Version.Build,Version.Platform,Version.Processor));
#elifGUANAQO_WITH_OPENBLAS
benchmark::AddCustomContext("blas_library","OpenBLAS");
benchmark::AddCustomContext("blas_version",OPENBLAS_VERSION);
#endif
#ifdefined(__INTEL_LLVM_COMPILER)
benchmark::AddCustomContext("compiler","intel-llvm");
benchmark::AddCustomContext("compiler_version",__VERSION__);
#elifdefined(__clang__)
benchmark::AddCustomContext("compiler","clang");
benchmark::AddCustomContext("compiler_version",__VERSION__);
#elifdefined(__GNUC__)
benchmark::AddCustomContext("compiler","gcc");
benchmark::AddCustomContext("compiler_version",__VERSION__);
#elifdefined(_MSC_VER)
benchmark::AddCustomContext("compiler","msvc");
benchmark::AddCustomContext("compiler_version",GUANAQO_STRINGIFY(_MSC_FULL_VER));
#endif
#ifdefined(__AVX512F__)
benchmark::AddCustomContext("arch","avx512f");
#elifdefined(__AVX2__)
benchmark::AddCustomContext("arch","avx2");
#elifdefined(__AVX__)
benchmark::AddCustomContext("arch","avx");
#elifdefined(__SSE3__)
benchmark::AddCustomContext("arch","sse3");
#elifdefined(__ARM_NEON)
benchmark::AddCustomContext("arch","neon");
#endif
#ifBATMAT_WITH_GSI_HPC_SIMD
benchmark::AddCustomContext("simd_library","GSI-HPC/simd");
#else
benchmark::AddCustomContext("simd_library","libstdc++<experimental/simd>");
#endif
}

intmain(intargc,char**argv)try{
#ifGUANAQO_WITH_PERFETTO
guanaqo::trace::initialize_tracing();
#endif
char*constprogram=argv[0];
CLI::Appapp{"CyQPALMandCyqloneSpring-MassBenchmarks"};
Optionsopts;
register_options(program,app,opts);
try{
app.parse(argc,argv);
}catch(constCLI::ParseError&e){
returnapp.exit(e);
}
export_problem(opts);
auto[problem_name_width,solver_name_width]=register_benchmarks(opts);
if(autoerr=initialize_google_benchmark(program,app.remaining(true));err!=0)
returnerr;
register_context();
autoreporter=opts.custom_reporter
?make_custom_reporter(problem_name_width,solver_name_width+2,
opts.print_extra,opts.use_color)
:nullptr;
benchmark::RunSpecifiedBenchmarks(reporter.get());
print_traces(std::cout);
benchmark::Shutdown();
}catch(conststd::exception&e){
std::cerr<<"Error:"<<e.what()<<std::endl;
returnEXIT_FAILURE;
}
